using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;

namespace Convenciones.LoadTest;

/// <summary>
/// Mints the HS256 token shape the local host accepts, so the harness drives the real API with
/// <c>Jwt:SigningKey</c> and no identity provider.
/// </summary>
/// <remarks>
/// The signing key is a throw-away local value generated by the harness; it is never read from the
/// environment and never written to a file or to the report.
/// </remarks>
public static class JwtTokenFactory
{
    public static string Create(
        Guid subject,
        string issuer,
        string audience,
        string signingKey,
        TimeSpan lifetime)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(issuer);
        ArgumentException.ThrowIfNullOrWhiteSpace(audience);
        ArgumentException.ThrowIfNullOrWhiteSpace(signingKey);

        var now = DateTimeOffset.UtcNow;
        var header = Base64Url(Encoding.UTF8.GetBytes("""{"alg":"HS256","typ":"JWT"}"""));
        var payload = Base64Url(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(new Dictionary<string, object>
        {
            ["sub"] = subject.ToString(),
            ["iss"] = issuer,
            ["aud"] = audience,
            ["iat"] = now.ToUnixTimeSeconds(),
            ["nbf"] = now.AddMinutes(-1).ToUnixTimeSeconds(),
            ["exp"] = now.Add(lifetime).ToUnixTimeSeconds(),
        })));

        var signature = Base64Url(HMACSHA256.HashData(
            Encoding.UTF8.GetBytes(signingKey),
            Encoding.ASCII.GetBytes($"{header}.{payload}")));

        return $"{header}.{payload}.{signature}";
    }

    private static string Base64Url(byte[] bytes) =>
        Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_');
}
